171:## Étape 5 — DEVDESK-376 : `dk setup` (S) — **parallélisable** avec 1 à 4 (ne touche pas le banc, sauf la ligne `ui/setup` de `pendingSpinnerImports`)
173:Fichiers : `ui/setup/{model,fields,styles}.go`, `model_test.go`.
191:Commande : `go test ./internal/ui/setup && go test ./internal/app -run BubblesSpinner`
216:- `dk setup` : un `●` fixe peut se lire comme « fait » ; le texte « Checking… » porte le sens (décision Q3).
	themeOptions []string
	themeIdx     int

	forgeTypeIdx int
	// forgeURLTouched stops the URL field from being overwritten once the user
	// has typed into it, so switching Forge back and forth does not clobber a
	// self-hosted URL they already entered.
	forgeURLTouched     bool
	forgeURLInput       textinput.Model
	forgeNamespaceInput textinput.Model
	visibilityValue     string
	cloneMethodIdx      int
	forgeTokenInput     textinput.Model

	// pending names the async step in flight, shown in the footer with a
	// spinner (Rule 128); empty when nothing is running.
	pending string
	footer  components.FooterMessage
	spinner spinner.Model

	savedPath             string
	currentContextWarning string
	tokenSaveWarning      string
}

// New builds the wizard with every field at its default value.
func New() Model {
	nameInput := textinput.New()
	nameInput.Placeholder = "e.g. work, staging"
	nameInput.CharLimit = 64
	nameInput.SetWidth(40)
	styleTextInput(&nameInput)
	nameInput.Focus()

	urlInput := textinput.New()
	urlInput.CharLimit = 200
	urlInput.SetWidth(50)
	styleTextInput(&urlInput)

	nsInput := textinput.New()
	nsInput.Placeholder = "optional"
	nsInput.CharLimit = 100
	nsInput.SetWidth(40)
	styleTextInput(&nsInput)

	tokenInput := textinput.New()
	tokenInput.Placeholder = "optional — can be set later via the auth view"
	tokenInput.CharLimit = 200
	tokenInput.SetWidth(50)
	tokenInput.EchoMode = textinput.EchoPassword
	styleTextInput(&tokenInput)

	themes, err := theme.ListThemes()
	if err != nil || len(themes) == 0 {
		themes = []string{"default"}
	}

	s := spinner.New()
	s.Spinner = spinner.Dot
	s.Style = spinnerStyle

	m := Model{
		contextNameInput:    nameInput,
		themeOptions:        themes,
		forgeURLInput:       urlInput,
		forgeNamespaceInput: nsInput,
		visibilityValue:     "private",
		forgeTokenInput:     tokenInput,
		spinner:             s,
	}
	m.forgeURLInput.SetValue(forge.VocabularyFor(config.ForgeTypes()[m.forgeTypeIdx]).ExampleURL)
	return m
}

// Init starts the cursor blink, the only thing the wizard needs on launch.
func (m Model) Init() tea.Cmd {
	return textinput.Blink
}

// Update is the single Elm-architecture entry point (Rule 110): every field
// mutation happens here, never inside a Cmd.
func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		return m, nil

	case tea.KeyPressMsg:
		return m.handleKeyMsg(msg)

	case tea.PasteMsg:
		return m.handlePaste(msg)

	case spinner.TickMsg:
		var cmd tea.Cmd
		m.spinner, cmd = m.spinner.Update(msg)
		return m, cmd

	case components.ConfirmModalYesMsg:
		return m.handleConfirmYes()

	case components.ConfirmModalNoMsg:
		return m.handleConfirmNo()

	case ContextExistsMsg:
		return m.handleContextExists(msg)

	case SecretBackendCheckedMsg:
		return m.handleSecretBackendChecked(msg)

}

// recheckSecretBackendCmd re-tests whichever secret backend is currently
// selected. Called on first arrival at the step and every time the answer
// changes.
func (m *Model) recheckSecretBackendCmd() tea.Cmd {
	m.secretBackendCheck = secretBackendChecking
	name := strings.TrimSpace(m.contextNameInput.Value())
	pref := secretBackendOptions[m.secretBackendIdx]
	return tea.Batch(m.spinner.Tick, checkSecretBackendCmd(name, pref))
}

// recheckContainerEngineCmd re-tests whichever container engine is currently
// selected. Called on first arrival at the step and every time the answer
// changes.
func (m *Model) recheckContainerEngineCmd() tea.Cmd {
	m.engineCheck = engineChecking
	pref := config.ContainerEngines()[m.containerEngineIdx]
	return tea.Batch(m.spinner.Tick, checkContainerEngineCmd(pref))
}

// onForgeTypeChanged keeps the URL placeholder and the visibility value
// consistent with the newly selected forge.
	name := strings.TrimSpace(m.contextNameInput.Value())
	if err := config.ValidateNewContextName(name); err != nil {
		if errors.Is(err, config.ErrReservedContextName) {
			return m, m.footer.Error("\"" + name + "\" is reserved — choose another name")
		}
		return m, m.footer.Error(err.Error())
	}
	m.contextNameInput.SetValue(name)
	m.pending = "Checking context name..."
	return m, tea.Batch(m.spinner.Tick, checkContextExistsCmd(name))
}

func (m Model) handleContextExists(msg ContextExistsMsg) (tea.Model, tea.Cmd) {
	body = "DevDesk needs somewhere to keep your forge token. \"auto\" tries your OS " +
		"keyring first, then git's credential helper, and falls back to " +
		"memory-only — nothing survives past this session — if neither is " +
		"available. Pick \"keyring\" or \"git-credential\" to require one " +
		"specifically instead of silently falling back."

	control = renderQuestionCycle("Secret backend", secretBackendOptions[m.secretBackendIdx])
	switch m.secretBackendCheck {
	case secretBackendChecking:
		control += "\n\n" + dimStyle.Render(m.spinner.View()+" Checking whether this is reachable...")
	case secretBackendReachable:
		control += "\n\n" + dimStyle.Render(m.secretBackendCheckDetail)
	case secretBackendUnreachable:
		control += "\n\n" + warnStyle.Render(m.secretBackendCheckDetail)
	}
	return "Where to store secrets", body, control
}

// containerEngineQuestion appends a live check of whether the selected
// engine's daemon actually answers — not just whether the binary is on
// PATH, which is all the rest of the app checks today.
func (m Model) containerEngineQuestion() (title, body, control string) {
	body = "DevDesk drives a container engine for image scanning and container " +
		"management. \"auto\" prefers Docker when it's on PATH and falls back " +
		"to Podman. Pick one explicitly if you have both installed and want " +
		"DevDesk to always use the same one."

	control = renderQuestionCycle("Container engine", config.ContainerEngines()[m.containerEngineIdx])
	switch m.engineCheck {
	case engineChecking:
		control += "\n\n" + dimStyle.Render(m.spinner.View()+" Checking whether it's running...")
	case engineReachable:
		control += "\n\n" + dimStyle.Render(m.engineCheckDetail)
	case engineUnreachable, engineMissing:
		control += "\n\n" + warnStyle.Render(m.engineCheckDetail)
	}
}

// renderFooterLine reads components.FooterMessage's state directly instead of
// calling its View — that method paints a full-width, background-filled,
// centered line (Rule 128), which is exactly what this screen opts out of.
func (m Model) renderFooterLine() string {
	if m.footer.IsSet() {
		return footerLevelStyle(m.footer.Level()).Render(m.footer.Text())
	}
	if m.pending != "" {
		return m.spinner.View() + " " + dimStyle.Render(m.pending)
	}
	return ""
}

